/bin/bash -lc 'tmpdir="${TMPDIR:-/tmp}"; python3 - "$tmpdir/sri_course_branch_tasks.tsv" "$tmpdir" > "$tmpdir/sri_verified_result.json" <<'"'PY'
from pathlib import Path
import json, sys, os, sqlite3, re

tasks_path = Path(sys.argv[1])
base = Path(sys.argv[2])

def norm(s):
    return s.strip()

# Read-only career tree query and exact breadcrumbs.
repo = Path.cwd()
db = sqlite3.connect(f'file:{(repo / \"assets/data/career_path.db\").as_posix()}?mode=ro', uri=True)
cur = db.cursor()
cur.execute('''WITH RECURSIVE tree(id, slug, name, parent_id, breadcrumb) AS (
 SELECT id, slug, name, parent_id, name FROM career_nodes WHERE parent_id IS NULL
 UNION ALL
 SELECT c.id, c.slug, c.name, c.parent_id, tree.breadcrumb || ' > ' || c.name
 FROM career_nodes c JOIN tree ON c.parent_id = tree.id
) SELECT id, slug, breadcrumb FROM tree''')
nodes = {row[0]: {'career_node_id': row[0], 'career_node_slug': row[1], 'career_breadcrumb': row[2]} for row in cur.fetchall()}
db.close()

# Mapping to local career tree. Each entry is (node id, relation, confidence, label issue).
def map_node(course, branch, typ):
    c, b = course.upper(), branch.upper()
    # Direct/nearest mappings for engineering and technology.
    eng_exact = {
        'COMPUTER SCIENCE AND ENGINEERING': (80, 'direct discipline', 'high', False),
        'CHEMICAL ENGINEERING': (86, 'direct discipline', 'high', False),
        'CIVIL ENGINEERING': (84, 'direct discipline', 'high', False),
        'ELECTRICAL ENGINEERING': (85, 'direct discipline', 'high', False),
        'ELECTRONICS AND COMMUNICATION ENGINEERING': (82, 'direct discipline', 'high', False),
        'MECHANICAL ENGINEERING': (83, 'direct discipline', 'high', False),
        'INFORMATION TECHNOLOGY': (89, 'direct discipline', 'high', False),
        'AERONAUTICAL ENGINEERING': (87, 'closest specialization: Aerospace Engineering', 'medium', True),
    }
    if c in {'BACHELOR OF ENGINEERING', 'BACHELOR OF ENGINEERING (LATERAL)'}:
        if b in eng_exact: return eng_exact[b]
        return (1, 'nearest-parent: B.Tech / B.E.', 'medium', False)
    if c == 'MASTER OF TECHNOLOGY':
        mt = {
            'COMPUTER SCIENCE AND ENGINEERING': (80, 'direct discipline', 'high', False),
            'INFORMATION TECHNOLOGY': (89, 'direct discipline', 'high', False),
            'DIGITAL COMMUNICATIONS': (82, 'closest specialization: Electronics & Communication', 'medium', False),
            'ELECTRICAL POWER SYSTEMS': (85, 'closest specialization: Electrical Engineering', 'medium', False),
            'POWER ELECTRONICS': (85, 'closest specialization: Electrical Engineering', 'medium', False),
            'STRUCTURAL DESIGN': (84, 'closest specialization: Civil Engineering', 'medium', False),
            'THERMAL ENGINEERING': (83, 'closest specialization: Mechanical Engineering', 'medium', False),
            'VLSI': (315, 'closest specialization: VLSI Design Engineer', 'medium', False),
            'INDUSTRIAL DESIGN': (239, 'closest specialization: Industrial Designer', 'medium', False),
        }
        return mt.get(b, (1, 'nearest-parent: B.Tech / B.E.', 'medium', False))
    if c in {'DIPLOMA ENGINEERING', 'DIPLOMA ENGINEERING (LATERAL)'}:
        de = {'CHEMICAL ENGINEERING':86, 'CIVIL ENGINEERING':84, 'COMPUTER SCIENCE AND ENGINEERING':80, 'ELECTRICAL ENGINEERING':85, 'MECHANICAL ENGINEERING':83}
        if b in de: return (11, 'direct programme family; branch nearest-parent', 'medium', False)
        return (11, 'direct discipline', 'high', False)
    if c in {'PH.D. (ENGINEERING & TECHNOLOGY)'}:
        if b in eng_exact: return eng_exact[b]
        return (1, 'nearest-parent: B.Tech / B.E.', 'medium', False)
    if c in {'BACHELOR OF  PHARMACY', 'BACHELOR OF PHARMACY  (LATERAL)', 'MASTER OF PHARMACY', 'DIPLOMA PHARMACY', 'DIPLOMA PHARMACY (AYURVED)', 'DIPLOMA PHARMACY (HOMOEOPATHY)'}:
        return (20, 'direct pharmacy discipline', 'high', True)
    if c == 'BACHELOR OF HOTEL MANAGEMENT AND CATERING TECHNOLOGY': return (79, 'direct discipline', 'high', False)
    if c == 'MASTERS IN BUSINESS ADMINISTRATION': return (208, 'closest specialization: MBA general management', 'medium', False)
    if c == 'BACHELOR OF EDUCATION': return (69, 'direct discipline', 'high', False)
    if c in {'BACHELOR OF PHYSICAL EDUCATION', 'BACHELOR OF PHYSICAL EDUCATION AND SPORTS'}: return (78, 'direct discipline', 'high', False)
    if c in {'BACHELOR IN MEDICAL LAB TECHNICIAN', 'MASTER OF MEDICAL LAB TECHNOLOGY [MMLT]', 'DIPLOMA MEDICAL LAB TECHNICIAN'}: return (37, 'closest discipline: DMLT (Medical Lab Technology)', 'medium', False)
    if c == 'BACHELOR OF PHYSIOTHERAPY' or c == 'MASTER OF PHYSIOTHERAPY (ORTHOPAEDIC)': return (23, 'direct physiotherapy discipline; postgraduate nearest-parent' if c.startswith('MASTER') else 'direct discipline', 'high' if c.startswith('BACHELOR') else 'medium', False)
    if c == 'DIPLOMA BLOOD TRANSFUSION': return (187, 'closest specialization: Blood Bank Technician', 'medium', False)
    if c == 'DIPLOMA DIALYSIS TECHNICIAN': return (339, 'nearest-parent: Paramedical & Health Sciences', 'medium', False)
    if c == 'DIPLOMA HUMAN NUTRITION': return (339, 'nearest-parent: Paramedical & Health Sciences', 'medium', False)
    if c == 'DIPLOMA X-RAY RADIOGRAPHER TECHNICIAN': return (38, 'closest specialization: Radiology & Imaging Technology', 'medium', False)
    if c == 'DIPLOMA YOGA': return (78, 'nearest-parent: Sports & Physical Education', 'low', False)
    if c == 'DIPLOMA PARAMEDICAL OPTHALMIC ASSISTENT': return (36, 'closest specialization: Optometry', 'low', False)
    if c == 'BACHELOR OF  LAW': return (347, 'nearest-parent: Law & Civil Services', 'medium', False)
    if c in {'BACHELOR OF HOMOEOPATHIC MEDICINE AND SURGERY', 'M.D. (HOMOEOPATHY)'}: return (18, 'direct discipline: BHMS/Homeopathy', 'high', False)
    if c == 'BACHELOR OF ARTS BACHELOR OF EDUCATION': return (69, 'closest specialization: B.Ed (Education)', 'medium', False)
    if c == 'BACHELOR OF LIBRARY AND INFORMATION SCIENCE': return (337, 'nearest-parent: Common Paths', 'low', False)
    if c == 'MASTER OF SCIENCE':
        ms = {'BOTANY':21, 'CHEMISTRY':25, 'COMPUTER SCIENCE':32, 'MATHEMATICS':2, 'MICROBIOLOGY':34, 'PHYSICS':24, 'ZOOLOGY':21}
        if b in ms: return (ms[b], 'closest discipline', 'medium', False)
        return (336, 'nearest-parent: Biology / PCB', 'low', False)
    if c == 'MASTER OF COMMERCE': return (198, 'closest specialization: M.Com', 'medium', False)
    if c == 'BACHELOR OF ARCHITECTURE': return (56, 'direct discipline', 'high', False)
    if c == 'PH.D. (SCIENCE)':
        phd = {'BIOTECHNOLOGY':21, 'BIOCHEMISTRY':35, 'BOTANY':21, 'CHEMISTRY':25, 'COMPUTER SCIENCE':32, 'ENVIRONMENTAL SCIENCE':26, 'FOOD SCIENCE AND NUTRITION':28, 'MATHEMATICS':2, 'MICROBIOLOGY':34, 'PHYSICS':24, 'ZOOLOGY':21, 'STATISTICS':6}
        if b in phd: return (phd[b], 'closest discipline', 'medium', False)
        return (337, 'nearest-parent: Common Paths', 'low', False)
    if c == 'PH.D.  (HUMANITIES, SOCIAL SCIENCES AND LANGUAGES)':
        phd = {'HISTORY':70, 'ECONOMICS':68, 'ENGLISH LITERATURE':72, 'HINDI LITERATURE':73, 'POLITICAL SCIENCE':71, 'PSYCHOLOGY':66, 'SOCIOLOGY':67, 'SOCIAL WORK':67}
        if b in phd: return (phd[b], 'closest discipline', 'medium', False)
        return (348, 'nearest-parent: Social Sciences & Education', 'low', False)
    if c == 'B.SC. (HONS.) AGRICULTURE': return (30, 'direct discipline', 'high', False)
    if c == 'PH.D. (COMMERCE)': return (198, 'closest specialization: M.Com / commerce', 'medium', False)
    if c == 'PH.D. (MANAGEMENT)': return (342, 'nearest-parent: Management & Business', 'medium', False)
    if c == 'POST GRADUATION DIPLOMA IN COMPUTER APPLICATION': return (3, 'closest discipline: BCA (Computer Applications)', 'medium', False)
    if c == 'BACHELOR OF DESIGN':
        bd = {'INDUSTRIAL DESIGN':239, 'TEXTILE DESIGN':237, 'INTERIOR DESIGN':233, 'PRODUCT DESIGN':232}
        if b in bd: return (bd[b], 'closest specialization', 'medium', False)
        return (55, 'direct programme family; communication design nearest-parent', 'medium', False)
    if c == 'BACHELOR OF DESIGN (LATERAL)': return (233, 'closest specialization: Interior Designer', 'medium', False)
    if c in {'BACHELOR OF ARTS (NEP)', 'BACHELOR OF ARTS NEP (SEMESTER)'}: return (348, 'nearest-parent: Social Sciences & Education', 'medium', False)
    if c == 'BACHELOR OF  AYURVEDIC MEDICINE AND SURGERY': return (17, 'direct discipline', 'high', False)
    if c == 'B.SC. (NURSING)': return (19, 'direct discipline', 'high', False)
    if c == 'BACHELOR OF COMMERCE NEP (SEMESTER)': return (42, 'direct discipline', 'high', False)
    if c == 'BACHELOR OF COMPUTER APPLICATION NEP (SEMESTER)': return (3, 'direct discipline', 'high', False)
    if c == 'BACHELOR OF BUSINESS ADMINISTRATION NEP (SEMESTER)': return (46, 'direct discipline', 'high', False)
    if c == 'BACHELOR OF SCIENCE NEP (SEMESTER)': return (337, 'nearest-parent: Common Paths', 'medium', False)
    if c == 'BACHELOR OF MEDICINE BACHELOR OF SURGERY': return (15, 'direct discipline', 'high', False)
    if c == 'B.A. L.L.B. (HONS.)': return (63, 'direct discipline', 'high', False)
    if c == 'PHD IN LAW': return (347, 'nearest-parent: Law & Civil Services', 'medium', False)
    raise ValueError((course, branch, typ))

# Exact current public admissions catalogue rows.
rows=[]
for line in tasks_path.read_text().splitlines():
    typ,typecode,exam,course,brcode,branch=line.split('\\t')
    course=norm(course); branch=norm(branch)
    fee_path=base/f'sri_api_fee_{typecode}_{exam}_{brcode}.json'
    data=json.loads(fee_path.read_text())
    fees=[]
    for rec in data if isinstance(data,list) else []:
        fees.extend(rec.get('FEESTURCUREELIGIBILITY') or [])
    fee=fees[0] if fees else {}
    node_id, relation, confidence, label_issue = map_node(course, branch, typ)
    node=dict(nodes[node_id])
    if typ=='ug': level, credential = 'undergraduate', 'bachelor_degree'
    elif typ=='pg': level, credential = 'postgraduate', 'master_degree'
    elif typ=='diploma': level, credential = 'diploma', 'diploma'
    elif typ=='doctoral': level, credential = 'doctoral', 'doctoral_degree'
    elif typ=='integrated': level, credential = 'integrated', 'integrated_degree'
    else: level, credential = 'postgraduate_diploma', 'postgraduate_diploma'
    duration = norm(fee.get('Course_Duration',''))
    eligibility = norm(fee.get('ELIGIBILITY',''))
    mapping={**node, 'relation':relation, 'confidence':confidence, 'mapping_status':'reviewed_with_career_tree_label_issue' if label_issue else 'reviewed_against_local_tree'}
    rows.append({
        'course_id': f'sssutms-{typecode}-{exam}-{brcode}',
        'name': course,
        'level': level,
        'credential': credential,
        'specialization': branch or None,
        'duration': f'{duration} years' if duration else None,
        'mode': {'ug':'UG','pg':'PG','diploma':'DIPLOMA','doctoral':'DOCTORAL','integrated':'INTEGRATED COURSE','pg_diploma':'PG DIPLOMA'}[typ],
        'eligibility': eligibility or None,
        'official_course_url': 'https://www.sssutms.co.in/erp/Student/Registration/Index/ojdZaOYsXtpmswGfjiVVww%3d%3d',
        'verification_status': 'verified_programme_family',
        'career_path_mappings': [mapping],
        'mapping_gap': None,
    })

